-- Translation + stability field for staging_insert_batch1..6.sql records.
-- Matches by source_pmid + exact original (Portuguese) evidence_summary, so it
-- is safe to run even if a pmid/locus combo repeats with different text.
-- Run against BOTH tables so future promotions from staging stay consistent.

-- ===== batch 1 =====

update known_safe_harbors set evidence_summary = 'In human iPSCs, CRISPR/Cas9 targeting AAVS1 to insert optogenetic/chemogenetic receptors (ChR2/hM4Di) resulted in silencing -- TRE3G BI promoter showed 95.3-98.2% methylation in iPSCs, vs. only 5.9% in HEK293T with the same construct. Hypomethylated clones also failed to express. Differentiation into neural stem cells did not reverse silencing.', stability = 'Silenced in iPSCs (95-98% methylation); silencing not reversed by neural differentiation' where source_pmid = '41468306' and evidence_summary = 'Em iPSCs humanas, CRISPR/Cas9 alvejando AAVS1 para inserir recetores optogenéticos/quimiogenéticos (ChR2/hM4Di) resultou em silenciamento -- promotor TRE3G BI com 95.3-98.2% de metilação em iPSCs, vs. apenas 5.9% em HEK293T com a mesma construção. Clones hipometilados também falharam em expressar. Diferenciação para estaminais neurais não reverteu.';
update public_safe_harbors_staging set evidence_summary = 'In human iPSCs, CRISPR/Cas9 targeting AAVS1 to insert optogenetic/chemogenetic receptors (ChR2/hM4Di) resulted in silencing -- TRE3G BI promoter showed 95.3-98.2% methylation in iPSCs, vs. only 5.9% in HEK293T with the same construct. Hypomethylated clones also failed to express. Differentiation into neural stem cells did not reverse silencing.', stability = 'Silenced in iPSCs (95-98% methylation); silencing not reversed by neural differentiation' where source_pmid = '41468306' and evidence_summary = 'Em iPSCs humanas, CRISPR/Cas9 alvejando AAVS1 para inserir recetores optogenéticos/quimiogenéticos (ChR2/hM4Di) resultou em silenciamento -- promotor TRE3G BI com 95.3-98.2% de metilação em iPSCs, vs. apenas 5.9% em HEK293T com a mesma construção. Clones hipometilados também falharam em expressar. Diferenciação para estaminais neurais não reverteu.';

update known_safe_harbors set evidence_summary = 'Transgenic mice with a human anti-SEB antibody inserted at ROSA26 maintained stable production for >140 weeks without compromising viability, with faithful germline transmission over 6 generations. KD=0.108nM.', stability = 'Stable >140 weeks in vivo' where source_pmid = '41341583' and evidence_summary = 'Ratinhos transgénicos com anticorpo humano anti-SEB inserido em ROSA26 mantiveram produção estável por >140 semanas sem comprometer viabilidade, com transmissão germinativa fiel por 6 gerações. KD=0.108nM.';
