update known_safe_harbors set evidence_summary = 'Macrophages isolated from Rosa26-Cas9 mice (Cas9-FZ line, Jackson Lab #026179, the most widely used worldwide) showed no defects in any commonly tested macrophage signaling pathway (RNA-seq + TLR3/TLR4/TRIF signaling immunoblot), contradicting an earlier report of differences.', stability = 'Not a duration study -- functional signaling assay only' where source_pmid = '41208113' and evidence_summary = 'Macrófagos isolados de ratinhos Rosa26-Cas9 (linha Cas9-FZ, Jackson Lab #026179, a mais usada globalmente) não mostraram defeitos em nenhuma via de sinalização macrofágica comummente testada (RNA-seq + imunoblot de sinalização TLR3/TLR4/TRIF), contrariando um relato anterior de diferenças.';
